mapper.select:
/*BATCH GroupStockList*/ SELECT TSIS.STOCK_ID, TSIW.STOCK_CODE, TO_CHAR(TSSA.MODIFY_DATE, (CASE WHEN #{stock_country_code}='KR' THEN 'YYYYMMDDHH24' ELSE 'YYYYMMDD' END )) AS MODIFY_DATE FROM TB_S_INTEREST_WATCHLIST TSIW LEFT JOIN ${analysisTable} TSSA ON TSIW.STOCK_CODE = TSSA.STOCK_CODE INNER JOIN TB_S_INTEREST_STOCK TSIS ON TSIW.STOCK_CODE = TSIS.STOCK_CODE WHERE 1=1 AND TSIS.STOCK_COUNTRY_CODE = #{stock_country_code}
AND ROWNUM <= TO_NUMBER(#{limit})
AND (TSSA.MODIFY_DATE IS NULL OR TO_CHAR(TSSA.MODIFY_DATE, (CASE WHEN #{stock_country_code}='KR' THEN 'YYYYMMDDHH24' ELSE 'YYYYMMDD' END )) != TO_CHAR(CURRENT_DATE, (CASE WHEN #{stock_country_code}='KR' THEN 'YYYYMMDDHH24' ELSE 'YYYYMMDD' END )))
GROUP BY TSIS.STOCK_ID, TSIW.STOCK_CODE, TSSA.STOCK_CLOSE, TSSA.MODIFY_DATE ORDER BY CASE WHEN MODIFY_DATE IS NULL THEN 0 ELSE 1 END, MODIFY_DATE
